package com.hupisan.view.main.adapter  import android.content.Context import android.content.Intent import android.graphics.Color import android.graphics.drawable.ColorDrawable import android.util.Log import android.view.LayoutInflater import android.view.View import android.view.ViewGroup import androidx.recyclerview.widget.RecyclerView import com.hupisan.R import com.hupisan.database.entity.DataModel import com.hupisan.databinding.RowNewDataBinding import com.hupisan.view.hutang.DetailHutangActivity import java.text.DecimalFormat import java.text.SimpleDateFormat import java.util.* import kotlin.collections.ArrayList   class NewAdapter(val context: Context): RecyclerView.Adapter<NewAdapter.ViewHolder>() {     var list = ArrayList<DataModel>()      fun setData(lists: ArrayList<DataModel>){         this.list = lists         notifyDataSetChanged()     }      private val vibrantLightColorList = arrayOf(         ColorDrawable(Color.parseColor("#9ACCCD")), ColorDrawable(Color.parseColor("#8FD8A0")),         ColorDrawable(Color.parseColor("#CBD890")), ColorDrawable(Color.parseColor("#DACC8F")),         ColorDrawable(Color.parseColor("#D9A790")), ColorDrawable(Color.parseColor("#D18FD9")),         ColorDrawable(Color.parseColor("#FF6772")), ColorDrawable(Color.parseColor("#DDFB5C"))     )      fun getRandomDrawbleColor(): ColorDrawable? {         val idx = Random().nextInt(vibrantLightColorList.size)         return vibrantLightColorList[idx]     }      inner class ViewHolder(val binding: RowNewDataBinding): RecyclerView.ViewHolder(binding.root){         fun bind(dataModel: DataModel){             val decimalFormat = DecimalFormat("##,###,###")             val todayString = SimpleDateFormat("dd/MM/yyyy", Locale.getDefault()).format(Date())              with(binding){                 if (dataModel.diBuat == todayString){                     tvLabelNew.visibility = View.VISIBLE                 } else {                     tvLabelNew.visibility = View.GONE                 }                  imvRandomColor.background = getRandomDrawbleColor()                 tvJumlahNominal.text = context.getString(R.string.dolar) + " " + decimalFormat.format(dataModel.jumlah)                 tvUsername.text = dataModel.username                 tvCreateAt.text = dataModel.diBuat             }         }     }      override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {         val binding = RowNewDataBinding.inflate(LayoutInflater.from(parent.context), parent, false)         return ViewHolder(binding)     }      override fun onBindViewHolder(holder: ViewHolder, position: Int) {         holder.bind(list[position])         holder.itemView.setOnClickListener {             DetailHutangActivity.STAY_MAIN_MENU = 101             val intent = Intent(context, DetailHutangActivity::class.java)             intent.putExtra(DetailHutangActivity.EXTRA_TYPE_JENIS, list[position].jenisPinjaman)             intent.putExtra(DetailHutangActivity.EXTRA_UID, list[position].id)             context.startActivity(intent)         }     }      override fun getItemCount()= list.size }  